//! Repository for SalesInvoice entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written SalesInvoice SQL (4-layer rule: services orchestrate, repos hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<SalesInvoice, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgPool, Row};
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::SalesInvoice;

/// Table name for SalesInvoice entities
pub const TABLE_NAME: &str = "billing.sales_invoices";

/// Repository for SalesInvoice entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct SalesInvoiceRepository(
    backbone_orm::GenericCrudRepository<SalesInvoice, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for SalesInvoiceRepository {
    type Target = backbone_orm::GenericCrudRepository<SalesInvoice, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl SalesInvoiceRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a draft Sales Invoice header insert writes.
///
/// Mirrors the raw column shape rather than the `SalesInvoice` entity: `status` and `posting_state`
/// are literal enum casts in the statement (`'draft'::invoice_status`, `'pending'::gl_posting_state`),
/// and the money columns arrive already rounded by the caller.
pub struct NewSalesInvoiceRow<'a> {
    pub id: Uuid,
    pub invoice_number: &'a str,
    pub company_id: Uuid,
    pub branch_id: Option<Uuid>,
    pub customer_id: Uuid,
    pub source_so_id: Option<Uuid>,
    pub posting_date: chrono::NaiveDate,
    pub due_date: Option<chrono::NaiveDate>,
    pub currency: &'a str,
    pub net_total: Decimal,
    /// Bound to the `tax_total` column — the Σ of the overlay's `output` basis lines.
    pub tax_total: Decimal,
    pub grand_total: Decimal,
    pub receivable_account_id: Uuid,
}

/// The A/R post builder's header projection.
pub struct ArHeaderRow {
    pub invoice_number: String,
    pub company_id: Uuid,
    pub branch_id: Option<Uuid>,
    pub customer_id: Uuid,
    pub source_so_id: Option<Uuid>,
    pub posting_date: chrono::NaiveDate,
    pub currency: String,
    pub grand_total: Decimal,
    pub receivable_account_id: Uuid,
}

/// An invoice's GL posting state + its reconciled accounting ids — the posted short-circuit probe.
pub struct PostingStateRow {
    /// `posting_state::text` — "pending" | "posted" | "failed".
    pub posting_state: String,
    pub journal_id: Option<Uuid>,
    pub accounting_post_id: Option<Uuid>,
}

/// The seam projection read after a winning pending→posted transition: what the SO seam needs.
pub struct SalesSeamHeaderRow {
    pub source_so_id: Option<Uuid>,
    pub grand_total: Decimal,
}

/// Hand-written SalesInvoice SQL. Lives here (not in the write service) per the module's 4-layer rule:
/// services orchestrate and own the unit of work, repositories hold the SQL.
impl SalesInvoiceRepository {
    /// Insert the draft A/R header. `outstanding_amount` starts at 0 — the posting transition sets it
    /// to `grand_total`.
    ///
    /// Takes the CALLER'S connection so the header, its lines, and the tax overlay commit as one unit.
    /// The caller has already bound the company on it (`bind_company_on`) — don't re-bind here.
    ///
    /// Returns the raw `sqlx::Error` deliberately: the caller inspects it for a unique violation to
    /// turn a duplicate invoice number into `DuplicateNumber`.
    pub async fn insert_draft(
        &self,
        conn: &mut sqlx::PgConnection,
        inv: &NewSalesInvoiceRow<'_>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO billing.sales_invoices
                (id, invoice_number, company_id, branch_id, customer_id, source_so_id, status,
                 posting_date, due_date, currency, net_total, tax_total, grand_total, outstanding_amount,
                 receivable_account_id, posting_state)
               VALUES ($1,$2,$3,$4,$5,$6,'draft'::invoice_status,$7,$8,$9,$10,$11,$12,0,$13,'pending'::gl_posting_state)"#,
        )
        .bind(inv.id).bind(inv.invoice_number).bind(inv.company_id).bind(inv.branch_id).bind(inv.customer_id)
        .bind(inv.source_so_id).bind(inv.posting_date).bind(inv.due_date).bind(inv.currency)
        .bind(inv.net_total).bind(inv.tax_total).bind(inv.grand_total).bind(inv.receivable_account_id)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Read the header the A/R post is built from. `Ok(None)` = no such live invoice in scope.
    ///
    /// ID-only: no company argument. `fetch_optional_row_scoped` means it rides a connection carrying
    /// the caller's `app.company_id` (ADR-0008), so it is fenced by the request/inherited scope.
    pub async fn fetch_ar_header(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<Option<ArHeaderRow>, sqlx::Error> {
        let row = company_scope::fetch_optional_row_scoped(
            pool,
            sqlx::query(
                r#"SELECT invoice_number, company_id, branch_id, customer_id, source_so_id, posting_date,
                          currency, grand_total, receivable_account_id
                   FROM billing.sales_invoices WHERE id=$1 AND (metadata->>'deleted_at') IS NULL"#,
            )
            .bind(invoice_id),
        )
        .await?;
        Ok(row.map(|r| ArHeaderRow {
            invoice_number: r.get("invoice_number"), company_id: r.get("company_id"),
            branch_id: r.get("branch_id"), customer_id: r.get("customer_id"),
            source_so_id: r.get("source_so_id"), posting_date: r.get("posting_date"),
            currency: r.get("currency"), grand_total: r.get("grand_total"),
            receivable_account_id: r.get("receivable_account_id"),
        }))
    }

    /// Probe the GL posting state for the posted short-circuit. `Ok(None)` = no such live invoice.
    ///
    /// ID-only, same request/inherited scope fence as [`Self::fetch_ar_header`].
    pub async fn fetch_posting_state(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<Option<PostingStateRow>, sqlx::Error> {
        let row = company_scope::fetch_optional_row_scoped(
            pool,
            sqlx::query(
                r#"SELECT posting_state::text AS ps, journal_id, accounting_post_id
                   FROM billing.sales_invoices WHERE id=$1 AND (metadata->>'deleted_at') IS NULL"#,
            )
            .bind(invoice_id),
        )
        .await?;
        Ok(row.map(|r| PostingStateRow {
            posting_state: r.get("ps"), journal_id: r.get("journal_id"),
            accounting_post_id: r.get("accounting_post_id"),
        }))
    }

    /// Read the accounting post id the credit note reverses. The outer `Option` is "no such live
    /// invoice"; the inner is "never posted". Same ID-only scope fence as above.
    pub async fn fetch_accounting_post_id(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<Option<Option<Uuid>>, sqlx::Error> {
        company_scope::fetch_optional_scalar_scoped(
            pool,
            sqlx::query_scalar(
                "SELECT accounting_post_id FROM billing.sales_invoices WHERE id=$1 AND (metadata->>'deleted_at') IS NULL",
            )
            .bind(invoice_id),
        )
        .await
    }

    /// Reconcile the invoice from the GL ack — the pending→posted transition. Guarded on
    /// `posting_state <> 'posted'` so exactly one of two concurrent posts wins; returns rows affected
    /// (0 = lost the race, and the loser must NOT re-publish the seam event).
    ///
    /// Record a GL rejection on the pool. The GL-rejected path runs outside the post transaction, so
    /// this stays pool-based (caller wraps it in `with_company_scope(Some(company))`).
    pub async fn mark_posting_failed(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<(), sqlx::Error> {
        company_scope::execute_scoped(
            pool,
            sqlx::query("UPDATE billing.sales_invoices SET posting_state='failed'::gl_posting_state WHERE id=$1")
                .bind(invoice_id),
        )
        .await?;
        Ok(())
    }

    // --- Transaction-accepting twins (outbox fence) -------------------------------------------
    // The caller has already bound the company scope onto `conn` (RLS), so these run the SAME SQL as
    // their pool counterparts directly on the shared transition transaction — staging the seam event
    // into the outbox atomically with the state change (mirrors backbone-payment).

    /// Transaction-accepting twin of [`Self::mark_posted`] — returns rows affected (1 = winner).
    pub async fn mark_posted_on(
        &self,
        conn: &mut sqlx::PgConnection,
        invoice_id: Uuid,
        journal_id: Uuid,
        post_id: Uuid,
    ) -> Result<u64, sqlx::Error> {
        let done = sqlx::query(
            r#"UPDATE billing.sales_invoices SET posting_state='posted'::gl_posting_state,
                status='submitted'::invoice_status, journal_id=$2, accounting_post_id=$3,
                posted_at=now(), outstanding_amount=grand_total
               WHERE id=$1 AND posting_state <> 'posted'::gl_posting_state"#,
        )
        .bind(invoice_id).bind(journal_id).bind(post_id)
        .execute(conn)
        .await?;
        Ok(done.rows_affected())
    }

    /// Transaction-accepting twin of [`Self::fetch_seam_header`].
    pub async fn fetch_seam_header_on(
        &self,
        conn: &mut sqlx::PgConnection,
        invoice_id: Uuid,
    ) -> Result<SalesSeamHeaderRow, sqlx::Error> {
        let row = sqlx::query("SELECT source_so_id, grand_total FROM billing.sales_invoices WHERE id=$1")
            .bind(invoice_id)
            .fetch_one(conn)
            .await?;
        Ok(SalesSeamHeaderRow {
            source_so_id: row.get("source_so_id"), grand_total: row.get("grand_total"),
        })
    }

    /// Transaction-accepting twin of [`Self::mark_cancelled`] — returns rows affected (1 = did it).
    pub async fn mark_cancelled_on(
        &self,
        conn: &mut sqlx::PgConnection,
        invoice_id: Uuid,
    ) -> Result<u64, sqlx::Error> {
        let done = sqlx::query(
            "UPDATE billing.sales_invoices SET status='cancelled'::invoice_status, outstanding_amount=0 WHERE id=$1 AND status <> 'cancelled'::invoice_status",
        )
        .bind(invoice_id)
        .execute(conn)
        .await?;
        Ok(done.rows_affected())
    }
}

backbone_core::impl_crud_repository!(SalesInvoiceRepository, SalesInvoice, soft_delete);
